alter table public.smollan_suppliers
 add column if not exists service_type text,
 add column if not exists associated_projects text[] not null default '{}',
 add column if not exists products text[] not null default '{}';

create table if not exists public.smollan_supplier_catalog_items (
 id uuid primary key default gen_random_uuid(),
 supplier_id uuid not null references public.smollan_suppliers(id) on delete cascade,
 item_type text not null,
 item_name text not null,
 description text,
 created_by uuid references auth.users(id) on delete set null,
 created_at timestamptz not null default now(),
 unique(supplier_id,item_type,item_name)
);
create index if not exists smollan_supplier_catalog_supplier_idx on public.smollan_supplier_catalog_items(supplier_id,item_type);
alter table public.smollan_supplier_catalog_items enable row level security;
drop policy if exists smollan_supplier_catalog_member_read on public.smollan_supplier_catalog_items;
create policy smollan_supplier_catalog_member_read on public.smollan_supplier_catalog_items for select to authenticated using (exists(select 1 from public.smollan_memberships m where m.user_id=auth.uid() and m.is_active and m.role in ('platform_admin','leadership','finance','procurement_production','activation_coordinator')));
drop policy if exists smollan_supplier_catalog_procurement_write on public.smollan_supplier_catalog_items;
create policy smollan_supplier_catalog_procurement_write on public.smollan_supplier_catalog_items for all to authenticated using (exists(select 1 from public.smollan_memberships m where m.user_id=auth.uid() and m.is_active and m.role in ('platform_admin','leadership','procurement_production'))) with check (exists(select 1 from public.smollan_memberships m where m.user_id=auth.uid() and m.is_active and m.role in ('platform_admin','leadership','procurement_production')));

